import{A as e,H as t,V as n,et as r}from"./chunks/framework.H6PnKRUW.js";var i=JSON.parse(`{"title":"技术栈","description":"","frontmatter":{},"headers":[],"relativePath":"intro/tech-stack.md","filePath":"intro/tech-stack.md"}`),a={name:`intro/tech-stack.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h1><h2 id="编写概况" tabindex="-1">编写概况 <a class="header-anchor" href="#编写概况" aria-label="Permalink to “编写概况”">​</a></h2><p>Syncraft 全部后端代码采用 <strong>Rust</strong>，AI 参与度很低，基本所有代码都是我手写的。这期间经历了各种复杂 API 和微软、麻将遗留问题的折磨，其中辛酸，在这个大 AI 时代似乎是一种宝贵的经验了。</p><h2 id="内部-crate-依赖关系" tabindex="-1">内部 Crate 依赖关系 <a class="header-anchor" href="#内部-crate-依赖关系" aria-label="Permalink to “内部 Crate 依赖关系”">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>依赖关系</th></tr></thead><tbody><tr><td><code>syncraft-protocol</code></td><td>无内部依赖，纯类型定义</td></tr><tr><td><code>console_info</code></td><td>被 core、server、mswrapper 共同引用，提供终端 UI</td></tr><tr><td><code>java_detect</code></td><td>被 core 引用，查找系统 Java</td></tr><tr><td><code>syncraft-core</code></td><td>依赖 protocol + console_info + java_detect</td></tr><tr><td><code>syncraft-server</code></td><td>依赖 protocol + console_info + mswrapper</td></tr><tr><td><code>mswrapper</code></td><td>依赖 console_info，可独立运行</td></tr></tbody></table><h2 id="主要依赖库" tabindex="-1">主要依赖库 <a class="header-anchor" href="#主要依赖库" aria-label="Permalink to “主要依赖库”">​</a></h2><table tabindex="0"><thead><tr><th>库</th><th>用途</th></tr></thead><tbody><tr><td>Axum</td><td>HTTP 服务框架，提供文件同步 API 与 Yggdrasil 验证路由</td></tr><tr><td>Tokio</td><td>异步运行时，贯穿所有网络与文件 I/O</td></tr><tr><td>Reqwest</td><td>HTTP 客户端，拉取 Mojang 资源、加载器安装包与同步清单</td></tr><tr><td>Serde</td><td>JSON / TOML 序列化，协议层与配置文件解析</td></tr><tr><td>SQLx</td><td>SQLite 数据库操作</td></tr><tr><td>Clap</td><td>CLI 参数解析，客户端与服务端均使用</td></tr><tr><td>BLAKE3</td><td>文件完整性哈希校验</td></tr><tr><td>Git2</td><td>libgit2 绑定，服务端用 Git 管理游戏文件版本</td></tr><tr><td>Argon2</td><td>密码哈希，用于 Yggdrasil 用户凭证存储</td></tr><tr><td>RSA</td><td>Yggdrasil 令牌签名与验证</td></tr><tr><td>Lettre</td><td>SMTP 邮件发送，支持注册邮箱验证</td></tr><tr><td>Inquire</td><td>交互式终端提示，客户端的选项选择与输入</td></tr><tr><td>Indicatif</td><td>进度条，下载与安装过程的视觉反馈</td></tr></tbody></table><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to “文档”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td>VitePress 2</td><td>静态站点生成，Vue 3 驱动</td></tr><tr><td>Bun</td><td>包管理与脚本运行</td></tr></tbody></table>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};